import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"40、【解】 坎下震上","description":"横渠易说 - 40、【解】 坎下震上","frontmatter":{"title":"40、【解】 坎下震上","description":"横渠易说 - 40、【解】 坎下震上"},"headers":[],"relativePath":"zh/classics/hengqu/042.md","filePath":"zh/classics/hengqu/042.md"}'),l={name:"zh/classics/hengqu/042.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_40、【解】-坎下震上" tabindex="-1">40、【解】 坎下震上 <a class="header-anchor" href="#_40、【解】-坎下震上" aria-label="Permalink to “40、【解】 坎下震上”">​</a></h1><h3 id="彖曰-解-险以动-动而免乎险-解。-解利西南-往得众也-其来复吉-乃得中也-有攸往夙吉-往有功也。天地解而雷雨作-雷雨作而百果草木皆甲坼-解之时大矣哉" tabindex="-1">彖曰：解，险以动，动而免乎险，解。“解利西南”，往得众也，“其来复吉”，乃得中也，“有攸往夙吉”，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲坼，解之时大矣哉! <a class="header-anchor" href="#彖曰-解-险以动-动而免乎险-解。-解利西南-往得众也-其来复吉-乃得中也-有攸往夙吉-往有功也。天地解而雷雨作-雷雨作而百果草木皆甲坼-解之时大矣哉" aria-label="Permalink to “彖曰：解，险以动，动而免乎险，解。“解利西南”，往得众也，“其来复吉”，乃得中也，“有攸往夙吉”，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲坼，解之时大矣哉!”">​</a></h3><h3 id="象曰-雷雨作-解-君子以赦过宥罪。" tabindex="-1">象曰：雷雨作，解，君子以赦过宥罪。 <a class="header-anchor" href="#象曰-雷雨作-解-君子以赦过宥罪。" aria-label="Permalink to “象曰：雷雨作，解，君子以赦过宥罪。”">​</a></h3><p>难免人患散，则得众者吉，往而不返，则生他变。有所往而不速，将后于时也，故无所往则静吉，有所往则速吉。</p><h3 id="初六-无咎。-象曰-刚柔之际-义无咎也。" tabindex="-1">初六，无咎。 象曰：刚柔之际，义无咎也。 <a class="header-anchor" href="#初六-无咎。-象曰-刚柔之际-义无咎也。" aria-label="Permalink to “初六，无咎。 象曰：刚柔之际，义无咎也。”">​</a></h3><p>险难方解，未护所安，近比于二，非其咎也。</p><h3 id="九二-田护三狐-得黄矢-贞吉。-象曰-九二贞吉-得中道也。" tabindex="-1">九二，田护三狐，得黄矢，贞吉。 象曰：九二贞吉，得中道也。 <a class="header-anchor" href="#九二-田护三狐-得黄矢-贞吉。-象曰-九二贞吉-得中道也。" aria-label="Permalink to “九二，田护三狐，得黄矢，贞吉。 象曰：九二贞吉，得中道也。”">​</a></h3><p>险乱方解，不正自疑之阴，皆自归附而顺听也，故曰“田护三狐”。不以三狐自累，上合于五，则得黄矢之象也。</p><h3 id="六三-负且乘-致寇至-贞吝。-象曰-负且乘-亦可丑也。自我致戎-又谁咎也" tabindex="-1">六三，负且乘，致寇至，贞吝。 象曰：“负且乘”，亦可丑也。自我致戎，又谁咎也! <a class="header-anchor" href="#六三-负且乘-致寇至-贞吝。-象曰-负且乘-亦可丑也。自我致戎-又谁咎也" aria-label="Permalink to “六三，负且乘，致寇至，贞吝。 象曰：“负且乘”，亦可丑也。自我致戎，又谁咎也!”">​</a></h3><p>不正而近比二刚，不能致一，故有小人负乘之象，贪以致寇也。</p><h3 id="九四-解而拇-朋至斯孚。-象曰-解而拇-未当位也。" tabindex="-1">九四，解而拇，朋至斯孚。 象曰：“解而拇”，未当位也。 <a class="header-anchor" href="#九四-解而拇-朋至斯孚。-象曰-解而拇-未当位也。" aria-label="Permalink to “九四，解而拇，朋至斯孚。 象曰：“解而拇”，未当位也。”">​</a></h3><p>位不当则所履者邪，故失位之阴因得骈附。险乱即解，解之则朋信。当一作正。</p><h3 id="六五-君子惟有解-吉。有孚于小人。-象曰-君子有解-小人退也。" tabindex="-1">六五，君子惟有解，吉。有孚于小人。 象曰：君子有解，小人退也。 <a class="header-anchor" href="#六五-君子惟有解-吉。有孚于小人。-象曰-君子有解-小人退也。" aria-label="Permalink to “六五，君子惟有解，吉。有孚于小人。 象曰：君子有解，小人退也。”">​</a></h3><p>君子道亨，则邪类之退必矣。</p><h3 id="上六-公用射隼于高墉之上-护之无不利。-象曰-公用射隼-以解悖也。" tabindex="-1">上六，公用射隼于高墉之上，护之无不利。 象曰：“公用射隼”，以解悖也。 <a class="header-anchor" href="#上六-公用射隼于高墉之上-护之无不利。-象曰-公用射隼-以解悖也。" aria-label="Permalink to “上六，公用射隼于高墉之上，护之无不利。 象曰：“公用射隼”，以解悖也。”">​</a></h3><p>忘义而贪，故以喻隼。</p>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
